        if (endpoint.isDefaultSendLibrary(address(this), eid)) revert InfraPathwayNotPinned(eid);
        (, bool isDefault) = endpoint.getReceiveLibrary(address(this), eid);
        if (isDefault) revert InfraPathwayNotPinned(eid);
    }
}

